/* Project-scoped design facts and customer preferences. Schematic colour study only. */
window.SHCustomerDesign=(()=>{
const pages=['Project information','Fixtures & finishes','Mood board'];
const categories=['Exterior roof','Exterior walls','Exterior joinery','Interior walls','Flooring','Kitchen','Bathroom'];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
function init(c){for(const key of ['projectFacts','finishSelections','finishSpecifications','moodboards','selectionMeasurements','supplierQuoteRequests'])if(!Array.isArray(c.store[key]))c.store[key]=[];if(c.projectId==='SH-TMP-DEMO-LOCKUP'&&!c.store.projectFacts.some(f=>f.projectId===c.projectId)){c.store.projectFacts.push({id:uid(),projectId:c.projectId,totalAreaM2:300,bedrooms:2,bathrooms:2,status:'Test reference — verify with SH',areaBasis:'Ground-floor area shown on A101; includes garage; total incl mezzanine unconfirmed',provenance:'User-supplied PLANS.pdf · A101 · 05/10/2026',notes:'Ground floor includes 177 m² garage. Bedrooms: Master Bed and Bed two. Bathrooms include ensuite. Test reference only, not a contracted design.'});if(c.save?.()===false)c.store.projectFacts.pop();}} 
const own=(c,key)=>c.store[key].filter(x=>x.projectId===c.projectId);
const canEdit=c=>['staff','customer'].includes(c.role);
function palette(){const p=window.SHColorsteelPalette||{};return {sourceUrl:p.sourceUrl,verifiedAt:p.verifiedAt,colours:(Array.isArray(p.colours)?p.colours:[]).filter(x=>x.id&&x.name&&/^#[0-9a-f]{6}$/i.test(x.hex))};}
function sourceLink(){const p=palette();try{const u=new URL(p.sourceUrl);if(u.protocol==='https:')return `<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">View COLORSTEEL source range ↗</a>${p.verifiedAt?` · checked ${esc(p.verifiedAt)}`:''}`;}catch{}return 'Palette awaiting a verified source.';}
const field=(name,label,value='',extra='')=>`<label>${esc(label)}<input name="${name}" value="${esc(value)}" ${extra}></label>`;
const area=(name,label,value='')=>`<label class="cd-wide">${esc(label)}<textarea name="${name}" rows="3" maxlength="3000">${esc(value)}</textarea></label>`;
function icon(kind){const paths={area:'M4 4h16v16H4z M8 4v4 M12 4v2 M16 4v4 M4 8h4 M4 12h2 M4 16h4',bed:'M3 18v-8h18v8 M3 15h18 M5 10V6h14v4 M7 10V8h4v2 M13 10V8h4v2',bath:'M3 12h18l-2 7H5z M6 12V5a2 2 0 0 1 4 0 M9 6h3 M6 19v2 M18 19v2'};return `<svg class="cd-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="${paths[kind]}"></path></svg>`;}
function factsCards(c){const f=own(c,'projectFacts')[0]||{},known=f.status==='SH confirmed'||String(f.status||'').startsWith('Test reference');return `<div class="cd-fact-grid">${[['area',String(f.status||'').startsWith('Test reference')?'Area shown on plan':'Total floor area',f.totalAreaM2,'m²'],['bed','Bedrooms',f.bedrooms,''],['bath','Bathrooms',f.bathrooms,'']].map(([kind,label,value,unit])=>`<div class="cd-fact">${icon(kind)}<div><span>${label}</span><strong>${known&&value!==''&&value!=null?`${esc(value)} ${unit}`:'To be confirmed'}</strong>${kind==='area'&&f.areaBasis?`<small>${esc(f.areaBasis)}</small>`:''}</div></div>`).join('')}</div><p class="small">${f.status?`${esc(f.status)} · ${esc(f.provenance||'Source not recorded')}`:'Project facts await Shed House confirmation. Model names alone do not establish floor area or room counts.'}${String(f.status||'').startsWith('Test reference')?' · Demonstration reference, not a contracted design.':''}</p>`;}
function panel(c){init(c);return `<section class="card cd-overview"><div class="card-top"><h2>Your project at a glance</h2><button class="secondary" data-cd-go="Project information">Project details →</button></div>${factsCards(c)}<div class="cd-links"><button class="link" data-cd-go="Fixtures & finishes">Fixtures, finishes & suppliers →</button><button class="link" data-cd-go="Mood board">Explore your colour preferences →</button></div></section>`;}
function information(c){const f=own(c,'projectFacts')[0]||{};return `<section class="card"><h2>${esc(c.project?.name||'Your Shed House')}</h2><p>${esc(c.project?.place||'Location awaiting confirmation')} · ${esc(c.projectId)}</p>${factsCards(c)}<p>${esc(f.notes||'No confirmed project notes recorded yet.')}</p><p class="small">Area basis: ${esc(f.areaBasis||'Awaiting measurement basis / drawing reference')}</p></section>${c.role==='staff'?`<section class="card"><h2>Shed House · Confirm project facts</h2><p>Use the actual agreed drawings and their revision. Leave unknown values blank. Test-plan information must remain labelled Test reference.</p><form id="cd-facts" class="cd-form">${field('totalAreaM2','Total floor area (m²)',f.totalAreaM2??'','type="number" min="0" step="0.01"')}${field('bedrooms','Bedrooms',f.bedrooms??'','type="number" min="0" step="1"')}${field('bathrooms','Bathrooms',f.bathrooms??'','type="number" min="0" step="0.5"')}<label>Fact status<select name="status">${['Unconfirmed','SH confirmed','Test reference','Test reference — verify with SH'].map(s=>`<option ${f.status===s?'selected':''}>${s}</option>`).join('')}</select></label>${field('provenance','Source document / revision / issue reference',f.provenance||'','required maxlength="250"')}${field('areaBasis','Measurement basis (e.g. internal floor area)',f.areaBasis||'','maxlength="250"')}${area('notes','Project notes',f.notes)}<p class="cd-error cd-wide" role="alert"></p><button class="primary">Save project facts</button></form></section>`:''}`;}
function finishes(c){return `<div class="cd-notice"><strong>Start with your base specification</strong><p>Shed House records the project’s base fixtures and finishes below. Customer supplier and product choices are draft preferences for assessment; saving a selection does not alter the contract, place an order or endorse a supplier.</p></div>${categories.map(category=>{const b=own(c,'finishSpecifications').find(x=>x.category===category)||{},s=own(c,'finishSelections').find(x=>x.category===category)||{};return `<section class="card"><h2>${category}</h2><div class="cd-finish-grid"><div><h3>Base specification</h3><p>${esc(b.specification||'Awaiting Shed House base specification.')}</p><p class="small">${esc(b.supplier||'Supplier not specified')}${b.product?` · ${esc(b.product)}`:''}<br>${esc(b.provenance||'Source / revision awaiting confirmation')}</p>${c.role==='staff'?`<details><summary>Edit SH base specification</summary><form data-cd-base="${esc(category)}" class="cd-form">${area('specification','Base fixtures / finish inclusions',b.specification)}${field('supplier','Base supplier (if specified)',b.supplier||'','maxlength="150"')}${field('product','Base product / reference',b.product||'','maxlength="200"')}${field('provenance','Specification / drawing reference',b.provenance||'','required maxlength="250"')}<p class="cd-error cd-wide" role="alert"></p><button class="secondary">Save base specification</button></form></details>`:''}</div><div><h3>Customer preference</h3>${canEdit(c)?`<form data-cd-selection="${esc(category)}" class="cd-form">${quantityFields(c,s,category)}${field('supplier','Preferred supplier / contact',s.supplier||'','maxlength="200"')}${field('product','Product / range',s.product||'','maxlength="200"')}${field('finish','Colour / finish',s.finish||'','maxlength="200"')}${area('notes','Selection notes and questions',s.notes)}<p class="small cd-wide">${esc(s.status||'Not selected')} · Confirm availability, suitability, price and scope with SH before ordering.</p><p class="cd-error cd-wide" role="alert"></p><button class="primary">Save preference</button></form>`:`<p>${esc(s.supplier||'No preference recorded')} · ${esc(s.product||'')}</p><p>${esc(s.finish||'')} ${esc(s.notes||'')}</p>`}</div></div></section>`;}).join('')}`;}
function mood(c){const m=own(c,'moodboards')[0]||{},p=palette();const roof=p.colours.find(x=>x.id===m.roofColourId),wall=p.colours.find(x=>x.id===m.wallColourId);const interiorWall=/^#[0-9a-f]{6}$/i.test(m.interiorWallColour||'')?m.interiorWallColour:'#f3ebe1',floor=/^#[0-9a-f]{6}$/i.test(m.interiorFloorColour||'')?m.interiorFloorColour:'#b49a7c';return `<div class="cd-notice"><strong>Shape your design preferences</strong><p>This schematic colour study is not your house render or a specification. Screen colours are approximate and do not guarantee a colour match; view actual supplier samples in natural light and confirm product availability and suitability with Shed House.</p></div><div class="cd-mood-grid"><section class="card"><h2>Exterior · Roof and walls</h2><svg class="cd-schematic" viewBox="0 0 640 350" role="img" aria-labelledby="cd-exterior-title"><title id="cd-exterior-title">Schematic gable house with ${esc(roof?.name||'unselected')} roof and ${esc(wall?.name||'unselected')} exterior walls</title><rect width="640" height="350" fill="#f1f3ed"/><path d="M30 295H610" stroke="#bdc9bf" stroke-width="2"/><path d="M110 160L270 75L510 140V290H110Z" data-cd-exterior-wall fill="${wall?.hex||'#c3c8c5'}" stroke="#20353c" stroke-width="2"/><path d="M270 75V290 M270 75L350 150V290" fill="none" stroke="#20353c" stroke-width="2"/><path d="M90 164L268 62L531 135L350 159L268 86L110 175Z" data-cd-exterior-roof fill="${roof?.hex||'#7b8585'}" stroke="#20353c" stroke-width="2"/><path d="M145 197h65v68h-65z M385 177h80v82h-80z" fill="#c4dce0" stroke="#20353c" stroke-width="4"/><path d="M281 202h39v88h-39z" fill="#f3ebe1" stroke="#20353c" stroke-width="3"/></svg><div class="cd-selected-colours"><span data-cd-colour-label="roof"><i style="background:${roof?.hex||'#7b8585'}"></i>Roof: ${esc(roof?.name||'Not selected')}</span><span data-cd-colour-label="wall"><i style="background:${wall?.hex||'#c3c8c5'}"></i>Walls: ${esc(wall?.name||'Not selected')}</span></div><p class="small">${sourceLink()}</p><p class="small">COLORSTEEL exterior colour references only. Availability varies by product and project location.</p></section><section class="card"><h2>Interior · Personal palette</h2><svg class="cd-schematic" viewBox="0 0 640 350" role="img" aria-label="Generic interior colour study, separate from COLORSTEEL exterior products"><rect data-cd-interior-wall width="640" height="350" fill="${interiorWall}"/><path data-cd-interior-floor d="M0 255H640V350H0Z" fill="${floor}"/><path d="M70 255V40H240V255" fill="#d6e2df" stroke="#20353c" stroke-width="4"/><path d="M390 270V210H565V270 M405 270V295 M550 270V295" fill="#e5dbcb" stroke="#20353c" stroke-width="3"/><circle cx="470" cy="175" r="26" fill="#faa21f" opacity=".65"/></svg><p class="small">Generic interior paint and material preferences. These are not COLORSTEEL interior paint products.</p></section></div>${canEdit(c)?`<section class="card"><h2>Save your mood board</h2><form id="cd-mood" class="cd-form">${['roof','wall'].map(part=>`<label>${part==='roof'?'Exterior roof':'Exterior wall'} · COLORSTEEL reference<select name="${part}ColourId"><option value="">No preference selected</option>${p.colours.map(x=>`<option value="${esc(x.id)}" ${m[`${part}ColourId`]===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`).join('')}${!p.colours.length?'<p class="small cd-wide">Verified exterior palette is not loaded yet; no exterior colour selection can be made.</p>':''}${field('interiorWallColour','Interior wall preference',interiorWall,'type="color"')}${field('interiorFloorColour','Interior floor preference',floor,'type="color"')}${area('notes','Mood board notes',m.notes)}<p class="small cd-wide">Change a selector to preview immediately; save to keep your preferences. Preferences are local and require SH confirmation before any contract variation.</p><p class="cd-error cd-wide" role="alert"></p><button class="primary">Save & preview preferences</button></form></section>`:''}`;}
function render(page,c){init(c);if(!pages.includes(page))return '';return `<div class="customer-design"><div class="heading"><div><div class="eyebrow">YOUR SHED HOUSE · DESIGN DETAILS</div><h1>${esc(page)}</h1><p>${esc(c.project?.name||c.projectId)}</p></div></div>${page==='Project information'?information(c):page==='Fixtures & finishes'?finishes(c)+rfqSection(c):mood(c)}</div>`;}
function validateFacts(d){for(const key of ['totalAreaM2','bedrooms','bathrooms'])if(d[key]!==''&&(!Number.isFinite(Number(d[key]))||Number(d[key])<0))throw Error('Project quantities must be non-negative numbers or blank.');if(d.bedrooms!==''&&!Number.isInteger(Number(d.bedrooms)))throw Error('Bedroom count must be a whole number.');if(!['Unconfirmed','SH confirmed','Test reference','Test reference — verify with SH'].includes(d.status)||!d.provenance?.trim())throw Error('Select a fact status and source reference.');return true;}
function validateMood(d){const p=palette();for(const key of ['roofColourId','wallColourId'])if(d[key]&&!p.colours.some(x=>x.id===d[key]))throw Error('Select a colour from the verified exterior palette.');for(const key of ['interiorWallColour','interiorFloorColour'])if(!/^#[0-9a-f]{6}$/i.test(d[key]||''))throw Error('Choose valid interior colour preferences.');return true;}
function saveRecord(c,key,match,data,form){const old=c.store[key].find(match),snapshot=old?{...old}:null;let record=old;if(!record){record={id:uid(),projectId:c.projectId};c.store[key].push(record);}Object.assign(record,data,{updatedAt:new Date().toISOString()});if(c.save()===false){if(snapshot){Object.keys(record).forEach(k=>delete record[k]);Object.assign(record,snapshot);}else c.store[key].splice(c.store[key].indexOf(record),1);form.querySelector('.cd-error').textContent='Could not save this change in browser storage.';return false;}return true;}
function bindPanel(c){document.querySelectorAll('[data-cd-go]').forEach(b=>b.onclick=()=>c.navigate(b.dataset.cdGo));}
function bind(page,c){init(c);bindPanel(c);bindPricing(c,page);const complete=()=>{c.toast('Project preferences saved in this browser.');c.navigate(page);};const facts=document.getElementById('cd-facts');if(facts&&c.role==='staff')facts.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(facts));try{validateFacts(d);const values={...d,totalAreaM2:d.totalAreaM2===''?null:Number(d.totalAreaM2),bedrooms:d.bedrooms===''?null:Number(d.bedrooms),bathrooms:d.bathrooms===''?null:Number(d.bathrooms)};if(saveRecord(c,'projectFacts',x=>x.projectId===c.projectId,values,facts)){c.toast('SH project facts saved.');c.navigate(page);}}catch(e){facts.querySelector('.cd-error').textContent=e.message;}};
document.querySelectorAll('[data-cd-base]').forEach(form=>{if(c.role!=='staff')return;form.onsubmit=e=>{e.preventDefault();const category=form.dataset.cdBase,d=Object.fromEntries(new FormData(form));if(!categories.includes(category)||!d.provenance.trim()){form.querySelector('.cd-error').textContent='A valid category and specification source are required.';return;}if(saveRecord(c,'finishSpecifications',x=>x.projectId===c.projectId&&x.category===category,{...d,category,status:'SH entered base specification'},form))complete();};});
document.querySelectorAll('[data-cd-selection]').forEach(form=>{if(!canEdit(c))return;form.onsubmit=e=>{e.preventDefault();const category=form.dataset.cdSelection;if(!categories.includes(category))return;const d=Object.fromEntries(new FormData(form));let q;try{q=validateQuantity(c,category,d);}catch(e){form.querySelector('.cd-error').textContent=e.message;return;}if(saveRecord(c,'finishSelections',x=>x.projectId===c.projectId&&x.category===category,{...d,...q,category,status:'Preference',selectedBy:c.role},form))complete();};});
const moodForm=document.getElementById('cd-mood');if(moodForm&&canEdit(c)){for(const part of ['roof','wall']){const select=moodForm.elements[part+'ColourId'];if(select)select.onchange=()=>{const colour=palette().colours.find(x=>x.id===select.value),fill=colour?.hex||(part==='roof'?'#7b8585':'#c3c8c5');document.querySelector('[data-cd-exterior-'+part+']')?.setAttribute('fill',fill);const label=document.querySelector('[data-cd-colour-label="'+part+'"]');if(label)label.innerHTML='<i style="background:'+fill+'"></i>'+ (part==='roof'?'Roof: ':'Walls: ')+esc(colour?.name||'Not selected');const title=document.getElementById('cd-exterior-title');if(title){const roof=palette().colours.find(x=>x.id===moodForm.elements.roofColourId.value),wall=palette().colours.find(x=>x.id===moodForm.elements.wallColourId.value);title.textContent='Schematic gable house with '+(roof?.name||'unselected')+' roof and '+(wall?.name||'unselected')+' exterior walls';}};}for(const [name,target]of [['interiorWallColour','wall'],['interiorFloorColour','floor']]){const input=moodForm.elements[name];if(input)input.oninput=()=>{if(/^#[0-9a-f]{6}$/i.test(input.value))document.querySelector('[data-cd-interior-'+target+']')?.setAttribute('fill',input.value);};}}
if(moodForm&&canEdit(c))moodForm.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(moodForm));try{validateMood(d);if(saveRecord(c,'moodboards',x=>x.projectId===c.projectId,{...d,status:'Preference',selectedBy:c.role,paletteSource:palette().sourceUrl||null},moodForm))complete();}catch(e){moodForm.querySelector('.cd-error').textContent=e.message;}};
}
const units=['m²','lm','ea'];
function normalUnit(unit){return ({m2:'m²','m²':'m²',m:'lm',lm:'lm',ea:'ea',each:'ea'})[String(unit||'').toLowerCase()]||'';}
function quantitySources(c,category){return [...(c.store.inventory||[]).filter(x=>x.projectId===c.projectId).map(x=>({key:'inventory:'+x.id,kind:'inventory',id:x.id,description:x.name,quantity:Number(x.qty),unit:normalUnit(x.unit),source:x.spec||x.sourceBOMId||'Inventory row',revision:x.version||''})),...own(c,'selectionMeasurements').filter(x=>x.category===category).map(x=>({...x,key:'measurement:'+x.id,kind:'measurement'}))];}
function quantityFields(c,s,category){const key=s.quantitySource?.kind&&s.quantitySource.kind!=='manual'?s.quantitySource.kind+':'+s.quantitySource.id:'manual';return `<label class="cd-wide">Quantity source<select name="quantitySourceKey"><option value="manual">Enter quantity manually</option>${quantitySources(c,category).map(x=>`<option value="${esc(x.key)}" ${key===x.key?'selected':''}>${esc(x.kind==='inventory'?'Inventory':'SH measurement')} · ${esc(x.description)} · ${esc(x.quantity)} ${esc(x.unit||'unsupported unit')}</option>`).join('')}</select></label>${field('quantity','Quantity required',s.quantity??'','type="number" min="0.0001" step="any"')}<label>Pricing unit<select name="unit">${units.map(u=>`<option ${s.unit===u?'selected':''}>${u}</option>`).join('')}</select><label class="cd-check cd-wide"><input type="checkbox" name="quantityReviewed" ${s.quantityReviewed?'checked':''}> I verified this quantity and unit against the actual project scope and source.</label><p class="small cd-wide">A selected inventory or SH measurement copies its quantity, unit and source reference. No automatic plan/PDF takeoff is performed. Manual quantities require your own measurement.</p><p class="small cd-wide" data-cd-source-preview>${esc(s.quantitySource?.source||'Choose a source or enter your own measured quantity.')} · ${esc(s.quantitySource?.revision||'Revision not specified')}</p>`;}
function validateQuantity(c,category,d,required=false){if(d.quantity===''||d.quantity==null){if(required)throw Error('A positive reviewed quantity is required before requesting pricing.');return {quantity:null,unit:units.includes(d.unit)?d.unit:'ea',quantitySource:{kind:'manual'},quantityReviewed:false};}const quantity=Number(d.quantity);if(!Number.isFinite(quantity)||quantity<=0||!units.includes(d.unit))throw Error('Enter a positive quantity and a valid m², lm or ea unit.');const key=d.quantitySourceKey||'manual';let quantitySource={kind:'manual',description:'Customer / SH manual quantity',source:'Manually entered and reviewed',revision:''};if(key!=='manual'){const row=quantitySources(c,category).find(x=>x.key===key);if(!row)throw Error('Quantity source does not belong to this project/category.');if(!row.unit||quantity!==Number(row.quantity)||d.unit!==row.unit)throw Error('Quantity and unit must match the selected source. Choose manual input to use an adjusted measured quantity.');quantitySource={kind:row.kind,id:row.id,description:row.description,source:row.source,revision:row.revision};}const reviewed=d.quantityReviewed===true||d.quantityReviewed==='on';if(required&&!reviewed)throw Error('Review and confirm the quantity before requesting pricing.');return {quantity,unit:d.unit,quantitySource,quantityReviewed:reviewed};}
function supplierEmail(s){const email=String(s?.email||s?.contactEmail||'').trim();return /^[A-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i.test(email)&&!/[\r\n]/.test(email)?email:'';}
function requestText(r){return `REQUEST FOR SUPPLIER PRICING — NOT SENT\nReference: ${r.id}\nProject: ${r.projectId}\nTo: ${r.supplierName}${r.supplierEmail?' <'+r.supplierEmail+'>':''}\nStatus: ${r.status}\n\n${r.lines.map(l=>`${l.category}: ${l.product||'Product to confirm'} / ${l.finish||'Finish to confirm'}\nQuantity: ${l.quantity} ${l.unit}\nSource: ${l.quantitySource.kind} — ${l.quantitySource.description||''}; ${l.quantitySource.source||''}; revision ${l.quantitySource.revision||'not specified'}`).join('\n\n')}\n\nNotes: ${r.notes||'None'}\nPlease advise supply price, GST basis, availability, freight, lead time, exclusions and quote validity.\nThis is a pricing enquiry, not an order or an agreed contract variation.\nNo private contractor costs are included.`;}
function rfqSection(c){return `<section class="card"><h2>Quantities & supplier pricing</h2><p>Save a measured quantity with each finish preference, then prepare a request to an SH-registered supplier. Review the exact recipient and specification before preparing an email or downloading the request. Nothing is sent automatically.</p>${canEdit(c)?`<form id="cd-rfq" class="cd-form"><label>Saved finish preference<select name="category"><option value="">Choose a preference</option>${own(c,'finishSelections').map(x=>`<option>${esc(x.category)}</option>`).join('')}</select></label><label>SH-registered supplier<select name="supplierId"><option value="">Choose supplier</option>${(c.store.suppliers||[]).map(s=>`<option value="${esc(s.id)}">${esc(s.name)} · ${esc(s.category||'Supplier')}${supplierEmail(s)?' · '+esc(supplierEmail(s)):' · Email awaiting SH'}</option>`).join('')}</select></label>${area('notes','Enquiry notes / scope boundaries')}<p class="cd-error cd-wide" role="alert"></p><button class="primary">Create draft for review</button></form>`:''}${own(c,'supplierQuoteRequests').map(r=>`<article class="cd-rfq-record"><span class="tag ${r.status==='Draft'?'amber':'grey'}">${esc(r.status)} · Not sent</span><h3>${esc(r.supplierName)}</h3><p>Recipient: ${esc(r.supplierEmail||'SH supplier email not configured; download request instead.')}</p>${r.lines.map(l=>`<p><strong>${esc(l.category)} · ${esc(l.product||'Product to confirm')}</strong><br>${esc(l.finish||'Finish to confirm')} · ${esc(l.quantity)} ${esc(l.unit)}<br><span class="small">Source: ${esc(l.quantitySource.kind)} · ${esc(l.quantitySource.description)} · ${esc(l.quantitySource.source)} · Revision ${esc(l.quantitySource.revision||'Not specified')}</span></p>`).join('')}<p>${esc(r.notes)}</p>${canEdit(c)&&r.status==='Draft'?`<form data-cd-ready="${esc(r.id)}"><label class="cd-check"><input type="checkbox" name="reviewed" required> I reviewed this supplier, specification, quantities, source and notes. Prepare this exact snapshot for supplier pricing.</label><p class="cd-error" role="alert"></p><button class="secondary">Mark ready for supplier</button></form>`:''}${canEdit(c)&&r.status==='Ready for supplier'?`<div class="cd-links"><button class="secondary" data-cd-rfq-download="${esc(r.id)}">Download pricing request (.txt)</button>${r.supplierEmail?`<button class="secondary" data-cd-rfq-mail="${esc(r.id)}">Prepare email draft</button>`:''}</div><p class="small">Your email app opens a draft only. Review attachments and send manually. This portal does not record delivery or a supplier response.</p>`:''}</article>`).join('')||'<p>No pricing request drafts for this project.</p>'}</section>${c.role==='staff'?`<section class="card"><h2>Shed House · Measured selection quantities</h2><p>Enter a checked kitset measurement with its source drawing/schedule revision. Customers can use these rows when preparing finish quantities.</p><form id="cd-measurement" class="cd-form"><label>Finish category<select name="category">${categories.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label>${field('description','Measured item description','','required maxlength="200"')}${field('quantity','Quantity','','required type="number" min="0.0001" step="any"')}<label>Unit<select name="unit">${units.map(x=>`<option>${x}</option>`).join('')}</select></label>${field('source','Drawing / schedule source','','required maxlength="250"')}${field('revision','Revision / issue reference','','required maxlength="100"')}<p class="cd-error cd-wide" role="alert"></p><button class="primary">Add checked measurement</button></form>${own(c,'selectionMeasurements').map(x=>`<p>${esc(x.category)} · ${esc(x.description)} · ${esc(x.quantity)} ${esc(x.unit)} · ${esc(x.source)} / ${esc(x.revision)}</p>`).join('')}</section>`:''}`;}
function buildRequest(c,d){const supplier=(c.store.suppliers||[]).find(s=>s.id===d.supplierId),selection=own(c,'finishSelections').find(s=>s.category===d.category);if(!supplier)throw Error('Choose an SH-registered supplier.');if(!selection||!categories.includes(selection.category))throw Error('Choose a saved finish preference for this project.');const key=selection.quantitySource?.kind&&selection.quantitySource.kind!=='manual'?selection.quantitySource.kind+':'+selection.quantitySource.id:'manual';const q=validateQuantity(c,selection.category,{...selection,quantitySourceKey:key},true);return {id:uid(),projectId:c.projectId,supplierId:supplier.id,supplierName:supplier.name,supplierEmail:supplierEmail(supplier),lines:[{category:selection.category,product:selection.product,finish:selection.finish,quantity:q.quantity,unit:q.unit,quantitySource:q.quantitySource}],notes:d.notes||'',status:'Draft',reviewedConfirmed:false,createdAt:new Date().toISOString()};}
function bindPricing(c,page){if(!canEdit(c))return;document.querySelectorAll('[data-cd-selection]').forEach(form=>{const select=form.elements.quantitySourceKey;if(select)select.onchange=()=>{const row=quantitySources(c,form.dataset.cdSelection).find(x=>x.key===select.value);if(row){form.elements.quantity.value=row.quantity;form.elements.unit.value=row.unit;}const preview=form.querySelector('[data-cd-source-preview]');if(preview)preview.textContent=row?row.description+' · '+row.source+' · Revision '+(row.revision||'Not specified'):'Manual quantity: verify against your actual measured scope.';form.elements.quantityReviewed.checked=false;};for(const name of ['quantity','unit'])if(form.elements[name])form.elements[name].onchange=()=>{form.elements.quantityReviewed.checked=false;};});const refresh=()=>c.navigate(page);const rfq=document.getElementById('cd-rfq');if(rfq)rfq.onsubmit=e=>{e.preventDefault();try{const r=buildRequest(c,Object.fromEntries(new FormData(rfq)));if(saveRecord(c,'supplierQuoteRequests',x=>x.id===r.id,r,rfq))refresh();}catch(e){rfq.querySelector('.cd-error').textContent=e.message;}};const measurement=document.getElementById('cd-measurement');if(measurement&&c.role==='staff')measurement.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(measurement));if(!categories.includes(d.category)||!Number.isFinite(Number(d.quantity))||Number(d.quantity)<=0||!units.includes(d.unit)||!d.source.trim()||!d.revision.trim()||!d.description.trim()){measurement.querySelector('.cd-error').textContent='Enter the category, positive measured quantity, unit, source and revision.';return;}const id=uid();if(saveRecord(c,'selectionMeasurements',x=>x.id===id,{...d,id,quantity:Number(d.quantity)},measurement))refresh();};document.querySelectorAll('[data-cd-ready]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const r=own(c,'supplierQuoteRequests').find(x=>x.id===form.dataset.cdReady);if(!r||r.status!=='Draft'||!new FormData(form).get('reviewed'))return;const previous={...r};Object.assign(r,{status:'Ready for supplier',reviewedConfirmed:true,reviewedAt:new Date().toISOString(),reviewedBy:c.role});if(c.save()===false){Object.keys(r).forEach(k=>delete r[k]);Object.assign(r,previous);form.querySelector('.cd-error').textContent='Could not save the reviewed request.';return;}refresh();});document.querySelectorAll('[data-cd-rfq-download]').forEach(b=>b.onclick=()=>{const r=own(c,'supplierQuoteRequests').find(x=>x.id===b.dataset.cdRfqDownload&&x.status==='Ready for supplier'&&x.reviewedConfirmed);if(!r)return;const url=URL.createObjectURL(new Blob([requestText(r)],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download=`${c.projectId}-pricing-request-${r.id}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});document.querySelectorAll('[data-cd-rfq-mail]').forEach(b=>b.onclick=()=>{const r=own(c,'supplierQuoteRequests').find(x=>x.id===b.dataset.cdRfqMail&&x.status==='Ready for supplier'&&x.reviewedConfirmed);if(!r||supplierEmail({email:r.supplierEmail})!==r.supplierEmail)return;const a=document.createElement('a');a.href=`mailto:${encodeURIComponent(r.supplierEmail)}?subject=${encodeURIComponent('Shed House pricing request '+c.projectId)}&body=${encodeURIComponent(requestText(r))}`;a.click();c.toast('Email draft prepared in your email app. Review and send manually; portal status remains not sent.');});}
return {pages,render,bind,panel,bindPanel,validateFacts,validateMood,validateQuantity,buildRequest,requestText};
})();
